15. func iamClient(ctx context.Context, awsConfig aws.Config, c *Config) *iam.Client {
16. 	logger := logging.RetrieveLogger(ctx)
17. 
18. 	return iam.NewFromConfig(awsConfig, func(opts *iam.Options) {
19. 		if c.IamEndpoint != "" {
20. 			logger.Info(ctx, "IAM client: setting custom endpoint", map[string]any{
21. 				"tf_aws.iam_client.endpoint": c.IamEndpoint,
22. 			})
23. 			opts.EndpointResolver = iam.EndpointResolverFromURL(c.IamEndpoint) //nolint:staticcheck // The replacement is not documented yet (2023/07/31)
24. 		}
25. 	})
26. }
27. 
28. func stsClient(ctx context.Context, awsConfig aws.Config, c *Config) *sts.Client {
29. 	logger := logging.RetrieveLogger(ctx)
30. 
31. 	return sts.NewFromConfig(awsConfig, func(opts *sts.Options) {
32. 		if c.StsRegion != "" {
33. 			logger.Info(ctx, "STS client: setting region", map[string]any{
34. 				"tf_aws.sts_client.region": c.StsRegion,
35. 			})
36. 			opts.Region = c.StsRegion
37. 		}
38. 		if c.StsEndpoint != "" {
39. 			logger.Info(ctx, "STS client: setting custom endpoint", map[string]any{
40. 				"tf_aws.sts_client.endpoint": c.StsEndpoint,
41. 			})
42. 			opts.EndpointResolver = sts.EndpointResolverFromURL(c.StsEndpoint) //nolint:staticcheck // The replacement is not documented yet (2023/07/31)
43. 		}
44. 	})
45. }
