20. const (
21. 	configSourceProviderConfig      = "provider"
22. 	configSourceEnvironmentVariable = "envvar"
23. )
24. 
25. func getCredentialsProvider(ctx context.Context, c *Config) (aws.CredentialsProvider, string, diag.Diagnostics) {
26. 	var diags diag.Diagnostics
27. 
28. 	logger := logging.RetrieveLogger(ctx)
29. 
30. 	loadOptions, err := commonLoadOptions(ctx, c)
31. 	if err != nil {
32. 		return nil, "", diags.AddSimpleError(err)
33. 	}
34. 	loadOptions = append(
35. 		loadOptions,
36. 		// The endpoint resolver is added here instead of in commonLoadOptions() so that it
37. 		// is not included in the aws.Config returned to the caller
38. 		config.WithEndpointResolverWithOptions(credentialsEndpointResolver(ctx, c)),
39. 		config.WithLogConfigurationWarnings(true),
40. 	)
41. 
42. 	envConfig, err := config.NewEnvConfig()
43. 	if err != nil {
44. 		return nil, "", diags.AddSimpleError(err)
45. 	}
46. 
47. 	if c.Profile != "" && os.Getenv("AWS_ACCESS_KEY_ID") != "" && os.Getenv("AWS_SECRET_ACCESS_KEY") != "" {
48. 		if c.UseLegacyWorkflow {
49. 			diags.AddWarning("Configuration conflict overridden",
50. 				`A Profile was specified along with the environment variables "AWS_ACCESS_KEY_ID" and "AWS_SECRET_ACCESS_KEY". `+
51. 					`The legacy workflow is enabled, so the Profile will be ignored in favor of the environment variable credentials. `+
52. 					`This behavior may be removed in the future.`)
53. 			c.Profile = ""
54. 		} else {
55. 			diags.AddWarning("Configuration conflict detected",
56. 				`A Profile was specified along with the environment variables "AWS_ACCESS_KEY_ID" and "AWS_SECRET_ACCESS_KEY". `+
57. 					`The Profile is now used instead of the environment variable credentials. This may lead to unexpected behavior.`)
58. 		}
59. 	}
60. 
61. 	// The default AWS SDK authentication flow silently ignores invalid Profiles. Pre-validate that the Profile exists
62. 	// https://github.com/aws/aws-sdk-go-v2/issues/1591
63. 	profile := c.Profile
64. 	var profileSource string
65. 	if profile != "" {
66. 		profileSource = configSourceProviderConfig
67. 	} else {
68. 		profile = envConfig.SharedConfigProfile
69. 		profileSource = configSourceEnvironmentVariable
70. 	}
71. 
72. 	if profile != "" {
73. 		logger.Debug(ctx, "Using profile", map[string]any{
74. 			"tf_aws.profile":        profile,
75. 			"tf_aws.profile.source": profileSource,
76. 		})
77. 		sharedCredentialsFiles, err := c.ResolveSharedCredentialsFiles()
78. 		if err != nil {
79. 			return nil, "", diags.AddSimpleError(err)
80. 		}
81. 		if len(sharedCredentialsFiles) != 0 {
82. 			f := make([]string, len(sharedCredentialsFiles))
83. 			for i, v := range sharedCredentialsFiles {
84. 				f[i] = fmt.Sprintf(`"%s"`, v)
85. 			}
86. 			logger.Debug(ctx, "Using shared credentials files", map[string]any{
87. 				"tf_aws.shared_credentials_files":        f,
88. 				"tf_aws.shared_credentials_files.source": configSourceProviderConfig,
89. 			})
90. 		} else {
91. 			if envConfig.SharedCredentialsFile != "" {
92. 				sharedCredentialsFiles = []string{envConfig.SharedCredentialsFile}
93. 				logger.Debug(ctx, "Using shared credentials files", map[string]any{
94. 					"tf_aws.shared_credentials_files":        sharedCredentialsFiles,
95. 					"tf_aws.shared_credentials_files.source": configSourceEnvironmentVariable,
96. 				})
97. 			}
98. 		}
99. 
100. 		sharedConfigFiles, err := c.ResolveSharedConfigFiles()
101. 		if err != nil {
102. 			return nil, "", diags.AddSimpleError(err)
103. 		}
104. 		if len(sharedConfigFiles) != 0 {
105. 			f := make([]string, len(sharedConfigFiles))
106. 			for i, v := range sharedConfigFiles {
107. 				f[i] = fmt.Sprintf(`"%s"`, v)
108. 			}
109. 			logger.Debug(ctx, "Using shared configuration files", map[string]any{
110. 				"tf_aws.shared_config_files":        f,
111. 				"tf_aws.shared_config_files.source": configSourceProviderConfig,
112. 			})
113. 		} else {
114. 			if envConfig.SharedConfigFile != "" {
115. 				sharedConfigFiles = []string{envConfig.SharedConfigFile}
116. 				logger.Debug(ctx, "Using shared configuration files", map[string]any{
117. 					"tf_aws.shared_config_files":        sharedConfigFiles,
118. 					"tf_aws.shared_config_files.source": configSourceEnvironmentVariable,
119. 				})
120. 			}
121. 		}
122. 
123. 		logger.Debug(ctx, "Loading profile", map[string]any{
124. 			"tf_aws.profile": profile,
125. 		})
126. 		_, err = config.LoadSharedConfigProfile(ctx, profile, func(opts *config.LoadSharedConfigOptions) {
127. 			if len(sharedCredentialsFiles) != 0 {
128. 				opts.CredentialsFiles = sharedCredentialsFiles
129. 			}
130. 			if len(sharedConfigFiles) != 0 {
131. 				opts.ConfigFiles = sharedConfigFiles
132. 			}
133. 		})
134. 		if err != nil {
135. 			return nil, "", diags.AddSimpleError(err)
136. 		}
137. 	}
138. 
139. 	// We need to validate both the configured and envvar named profiles for validity,
140. 	// but to use proper precedence, we only set the configured named profile
141. 	if c.Profile != "" {
142. 		logger.Debug(ctx, "Setting profile", map[string]any{
143. 			"tf_aws.profile":        profile,
144. 			"tf_aws.profile.source": configSourceProviderConfig,
145. 		})
146. 		loadOptions = append(
147. 			loadOptions,
148. 			config.WithSharedConfigProfile(c.Profile),
149. 		)
150. 	}
151. 
152. 	if c.AccessKey != "" || c.SecretKey != "" || c.Token != "" {
153. 		params := make([]string, 0, 3) //nolint:gomnd
154. 		if c.AccessKey != "" {
155. 			params = append(params, "access key")
156. 		}
157. 		if c.SecretKey != "" {
158. 			params = append(params, "secret key")
159. 		}
160. 		if c.Token != "" {
161. 			params = append(params, "token")
162. 		}
163. 		logger.Debug(ctx, "Using authentication parameters", map[string]any{
164. 			"tf_aws.auth_fields":        params,
165. 			"tf_aws.auth_fields.source": configSourceProviderConfig,
166. 		})
167. 		loadOptions = append(
168. 			loadOptions,
169. 			config.WithCredentialsProvider(
170. 				credentials.NewStaticCredentialsProvider(
171. 					c.AccessKey,
172. 					c.SecretKey,
173. 					c.Token,
174. 				),
175. 			),
176. 		)
177. 	}
178. 
179. 	logger.Debug(ctx, "Loading configuration")
180. 	cfg, err := config.LoadDefaultConfig(ctx, loadOptions...)
181. 	if err != nil {
182. 		return nil, "", diags.AddSimpleError(err)
183. 	}
184. 
185. 	// This can probably be configured directly in commonLoadOptions() once
186. 	// https://github.com/aws/aws-sdk-go-v2/pull/1682 is merged
187. 	if c.AssumeRoleWithWebIdentity != nil {
188. 		if c.AssumeRoleWithWebIdentity.RoleARN == "" {
189. 			return nil, "", diags.AddError("Assume Role With Web Identity", "Role ARN was not set")
190. 		}
191. 		if c.AssumeRoleWithWebIdentity.WebIdentityToken == "" && c.AssumeRoleWithWebIdentity.WebIdentityTokenFile == "" {
192. 			return nil, "", diags.AddError("Assume Role With Web Identity", "One of WebIdentityToken, WebIdentityTokenFile must be set")
193. 		}
194. 		provider, d := webIdentityCredentialsProvider(ctx, cfg, c)
195. 		diags = diags.Append(d...)
196. 		if diags.HasError() {
197. 			return nil, "", diags
198. 		}
199. 		cfg.Credentials = provider
200. 	}
201. 
