 	}
 	in.Request = smithyRequest

 	start := time.Now()

 	out, metadata, err = next.HandleDeserialize(ctx, in)

 	elapsed := time.Since(start)

 	if err == nil {
 		smithyResponse, ok := out.RawResponse.(*smithyhttp.Response)
