291. 			opts.ExternalID = aws.String(ar.ExternalID)
292. 		}
293. 
294. 		if ar.Policy != "" {
295. 			opts.Policy = aws.String(ar.Policy)
296. 		}
297. 
298. 		if len(ar.PolicyARNs) > 0 {
299. 			opts.PolicyARNs = getPolicyDescriptorTypes(ar.PolicyARNs)
300. 		}
301. 
