 	if !ok {
 		return out, metadata, fmt.Errorf("unknown request type %T", in.Request)
 	}

 	rc := smithyRequest.Build(ctx)

 	requestFields, err := logging.DecomposeHTTPRequest(ctx, rc)
 	if err != nil {
 		return out, metadata, fmt.Errorf("decomposing request: %w", err)
